'use strict';
// Preparation follows the audit workflow: scope, original document, extraction rules.
const efBase={workbench,configPanel,handleAction,render,closeModal,validate,modalContent};
const efView={tab:'original',panel:'preview',preview:null,settings:false};
function efPreparing(){return state.view==='tool'&&state.toolId==='extract'&&!currentTask();}
// Tool attachment association is independent of folder editing, matching OcrLeftSidebar.
function efCanLink(d){return (efPreparing()||state.view==='tool'&&!currentTask()&&!['engineering','association','bidding'].includes(state.toolId))&&!!d&&auditFileAccess(d).analyze&&d.can_manage_attachments!==false;}
function efChoices(){
 const c=ewConfig();if(efView.configRef!==c){efView.configRef=c;efView.resetFields=true;efView.validationAttempted=false;}if(currentTask())return c.fieldDefs.map(f=>({...f}));
 const fingerprint=JSON.stringify(c.fieldDefs);
 // Migrate the former checkbox draft using only the fields actually configured for execution.
 if(c.extractionFieldChoices?.version!==2||c.extractionFieldChoices.fingerprint!==fingerprint){c.extractionFieldChoices={version:2,fingerprint,fields:c.fieldDefs.map(f=>({...f}))};efView.resetFields=true;}
 return c.extractionFieldChoices.fields;
}
function efCommit(){const c=ewConfig(),fields=efChoices(),before=JSON.stringify(c.fieldDefs);c.fieldDefs=fields.map(f=>({name:String(f.name||'').trim(),description:String(f.description||'').trim()}));c.fields=c.fieldDefs.map(f=>f.name);c.extractionFieldChoices.fingerprint=JSON.stringify(c.fieldDefs);if(before!==JSON.stringify(c.fieldDefs))delete c.backendTemplateId;persist();}
function efErrors(){const f=efChoices(),names=f.map(x=>x.name.trim());return !f.length?'请至少添加一个提取字段':names.some(n=>!n)?'请填写字段名称':new Set(names).size!==names.length?'字段名称不能重复':'';}
function efRefreshCounts(){const c=ewConfig(),fields=efChoices();$$('[data-ef-count]').forEach(n=>n.textContent=fields.length);const names=fields.map(f=>f.name.trim());fields.forEach((f,i)=>{const input=$('#ef-field-'+i);if(input)input.setAttribute('aria-invalid',String(!f.name.trim()||names.filter(n=>n===f.name.trim()).length>1));});const error=$('#ef-field-error');if(error)error.textContent=fields.length||efView.validationAttempted?efErrors():'';if(!currentTask()){const save=$('.ef-config [data-action=ef-save-template]');if(save)save.disabled=!!efErrors();const run=$('.ew-command-actions [data-action=run]');if(run){run.disabled=!ewDocs().length||!fields.length;run.title=!ewDocs().length?'请先添加资料':!fields.length?'请先选择模板或添加字段':'提取左侧全部 '+ewDocs().length+' 份资料';}}const status=$('#ef-template-status'),t=xtFind(c.extractionTemplateId)||xtAll().find(t=>t.name===c.template);if(status){status.hidden=false;status.textContent=currentTask()?'本任务使用的字段，只读保留。':t&&JSON.stringify(xtAppliedFields(t))===JSON.stringify(c.fieldDefs)?'每个字段对应一列结果，可修改名称和提取说明。':!fields.length?'选择模板载入字段，或点击“添加字段”自行配置。':!c.template?'当前为自定义字段，可保存为个人模板复用。':'已调整本次字段，可另存为个人模板复用。';}}
function efFieldRows(locked){return efChoices().map((f,i)=>'<article class="ef-field" data-ef-row="'+i+'"><div class="ef-field-heading"><span class="ef-field-number">'+(i+1)+'</span><input id="ef-field-'+i+'" data-ef-input="name" data-index="'+i+'" aria-label="字段'+(i+1)+'名称" aria-required="true" value="'+E(f.name)+'" placeholder="字段名称（必填）" maxlength="100" '+(locked?'readonly':'')+'>'+(!locked?'<details class="lib-dropdown ef-field-menu"><summary class="iconbtn" aria-label="字段'+(i+1)+'更多操作">'+I('more','icon-sm')+'</summary><div class="lib-menu">'+B('上移字段','ef-field-up','ghost sm','data-index="'+i+'" '+(!i?'disabled':''))+B('下移字段','ef-field-down','ghost sm','data-index="'+i+'" '+(i===efChoices().length-1?'disabled':''))+'<div class="xt-menu-divider"></div>'+B('移除字段','ef-field-remove','ghost danger sm','data-index="'+i+'"')+'</div></details>':'')+'</div><textarea data-ef-input="description" data-index="'+i+'" aria-label="字段'+(i+1)+'提取说明" placeholder="提取说明：从哪里取值、取值范围或输出要求（选填）" rows="2" '+(locked?'readonly':'')+'>'+E(f.description||'')+'</textarea></article>').join('');}
configPanel=function(){
 if(state.toolId!=='extract')return efBase.configPanel();const c=ewConfig(),locked=!!currentTask(),fields=efChoices();
 return '<aside class="config ew-config ef-config" aria-label="Step 3 设置提取字段"><div class="ew-panel-head"><h2><span class="ef-step">Step 3</span>设置提取字段</h2>'+(locked?tag('执行时配置'):'')+'</div><div class="ef-template"><div class="ef-template-header"><label for="ef-template-select">提取模板</label>'+(!locked?B('另存为个人模板','ef-save-template','ghost sm ef-save-as','title="将当前字段保存为个人模板，原模板保留" '+(efErrors()?'disabled':'')):'')+'</div>'+ewSelect(c,locked).replace('<select ','<select id="ef-template-select" ')+'<p id="ef-template-status">'+(locked?'本任务使用的字段，只读保留。':fields.length?'每个字段对应一列结果，可修改名称和提取说明。':'选择模板载入字段，或点击“添加字段”自行配置。')+'</p></div><div class="ef-fields-head"><h3>提取字段 <strong data-ef-count>'+c.fieldDefs.length+'</strong></h3>'+(!locked?B(I('plus','icon-sm')+'添加字段','ef-field-add','sm ef-add-field'):'')+'</div><div class="ef-fields-scroll">'+efFieldRows(locked)+(!fields.length?'<div class="ew-empty-small">请配置需要提取的字段，至少添加1个字段。</div>':'')+'</div><div class="ef-config-bottom"><p class="error" id="ef-field-error" role="alert">'+(!locked&&(fields.length||efView.validationAttempted)?E(efErrors()):'')+'</p><details class="ef-settings" '+(efView.settings?'open':'')+'><summary>'+I('settings','icon-sm')+'附件与提取设置'+I('down','icon-sm')+'</summary><div class="ef-settings-body"><label class="ew-switch"><span>合并关联附件提取</span><input type="checkbox" role="switch" aria-label="附件内容合并到主文件" data-config="merge" '+(c.merge?'checked':'')+' '+(locked?'disabled':'')+'></label><p class="hint">'+(c.merge?'主文件与关联附件作为整体提取。':'仅提取主文件；已关联附件不参与取值。')+'</p>'+A(locked?'查看关联附件':'管理关联附件','attachments')+'<div class="ew-number-grid"><label>切片字数<input aria-label="切片字数" type="number" min="1000" max="50000" data-config="chunk" value="'+E(c.chunk)+'" '+(locked?'disabled':'')+'></label><label>冗余字数<input aria-label="冗余字数" type="number" min="0" max="5000" data-config="overlap" value="'+E(c.overlap)+'" '+(locked?'disabled':'')+'></label></div><p class="hint">长文分段处理，冗余为相邻分段重叠字数。</p>'+'</div></details>'+(locked?'<p class="ef-apply-note">任务配置为执行时快照</p>':'')+'</div></aside>';
};
function efMaterials(){
 const docs=ewDocs(),task=currentTask(),q=ws().treeQuery||'',matched=docs.filter(d=>(d.name+' '+ewPath(d)).toLowerCase().includes(q.toLowerCase())),shown=typeof wnWindow==='function'?wnWindow(matched,q):matched,spaces=SPACE_ORDER.filter(s=>shown.some(d=>d.space===s)),tree=document.createElement('div');
 tree.innerHTML=spaces.map(space=>'<div class="ew-space">'+E(space)+'</div>'+ewTree(space,'',shown.filter(d=>d.space===space))).join('');
 tree.querySelectorAll('.ew-file').forEach(row=>{
  const button=row.querySelector('[data-action="preview"]'),d=file(button.dataset.id),status=button.querySelector('small'),ids=raAttachmentIds(d,task),canLink=efCanLink(d);
  const info=document.createElement('div');info.className='ef-material-info';button.remove();status?.remove();info.append(button);
  const meta=document.createElement('div');meta.className='ef-material-meta';if(status&&status.textContent.trim()!=='解析完成')meta.append(status);
  meta.insertAdjacentHTML('beforeend','<div class="ef-material-actions">'+B(I('paperclip','icon-sm'),'attachments','ghost sm ef-material-attachments'+(ids.length?' has-attachments':''),'data-id="'+E(d.id)+'" aria-label="'+(canLink?'关联':'查看')+E(d.name)+'的附件" title="'+(task?'查看执行时关联的附件':!canLink?'当前仅可查看附件，无关联修改权限':ids.length?'已关联 '+ids.length+' 份附件，点击管理':'为此文件关联合同附件、清单等补充资料')+'"')+(!task?B(I('close','icon-sm'),'ef-remove-material','ghost sm ef-remove-material','data-id="'+E(d.id)+'" aria-label="移出本次提取 '+E(d.name)+'" title="仅移出本次提取，不删除资料库原文件"'):'')+'</div>');
  info.append(meta);row.append(info);
 });
 return '<aside class="ew-materials" aria-label="Step 1 添加资料"><div class="ew-panel-head ef-material-head tw-panel-head"><h2><span class="tw-step">Step 1</span>添加资料</h2>'+B('添加','add-tool-materials','soft sm','aria-label="添加提取资料"')+'</div><div class="ef-material-intro">'+(task?'下方为本次任务使用的资料。':'点击“添加”选择文件，下方为已选资料。')+'</div><div class="ew-material-controls">'+'<div class="search"><span>'+I('search','icon-sm')+'</span><input id="ew-tree-query" data-ew-input="tree-query" aria-label="查找本次资料" placeholder="查找已添加的文件或目录" value="'+E(q)+'"></div></div><div class="ew-tree">'+tree.innerHTML+(!docs.length?'<div class="tw-empty-small">点击上方“添加”，选择本次需要提取的文件。</div>':!shown.length?'<div class="ew-empty-small">没有匹配资料，查找不会改变提取范围。</div>':'')+'</div>'+(typeof wnMaterialPager==='function'?wnMaterialPager(): '')+'<div class="ew-scope-note">'+(task?'本次资料 <strong>'+docs.length+'</strong> 份':'已选 <strong>'+docs.length+'</strong> 份资料')+'</div></aside>';
}
modalContent=function(){if(modal!=='ef-save-template')return efBase.modalContent();const d=modalData.draft;return modalFrame('另存为个人模板','保存当前字段和提取说明，下次选择此模板即可复用。','<div class="ef-save-summary">将保存 <strong>'+d.rules.length+'</strong> 个提取字段，原模板保留。</div><label class="field"><span>模板名称 <b class="red">*</b></span><input id="xt-template-name" data-ef-save="name" maxlength="100" value="'+E(d.name)+'" placeholder="输入便于识别的模板名称"></label><label class="field"><span>保存到</span><select data-ef-save="folderId" aria-label="个人模板分类">'+xtPersonalOptions(d.folderId)+'</select></label><label class="field"><span>模板描述（选填）</span><textarea data-ef-save="description" rows="2" placeholder="说明适用资料或审计用途">'+E(d.description)+'</textarea></label><p id="xt-editor-error" class="error" role="alert">'+E(modalData.error||'')+'</p>',B('取消','close-modal')+B('保存个人模板','ef-confirm-save-template','primary'),'ef-save-dialog');};
function efPreview(){const d=file(ws().preview),allowed=d&&auditFileAccess(d).preview;return '<section class="ef-preview" aria-label="Step 2 查看原文"><div class="ew-panel-head ef-preview-head"><h2><span class="ef-step">Step 2</span>查看原文</h2>'+(d?B(I('expand','icon-sm'),'source','ghost sm','data-id="'+E(d.id)+'" aria-label="对照查看原文件与解析内容" title="对照查看原文件与解析内容"')+'<details class="lib-dropdown ef-preview-menu"><summary class="iconbtn" aria-label="更多预览操作">'+I('more','icon-sm')+'</summary><div class="lib-menu">'+B(I('refresh','icon-sm')+'刷新原文件','ef-refresh-original','ghost sm',allowed?'':'disabled')+B(I('download','icon-sm')+'下载原文件','ef-download-original','ghost sm',allowed&&auditFileAccess(d).download?'':'disabled')+'</div></details>':'')+'</div>'+(d?'<div class="ef-preview-caption" title="'+E(ewPath(d))+'"><div><strong title="'+E(d.name)+'">'+E(d.name)+'</strong><span title="'+E(ewPath(d))+'">'+E(ewPath(d))+'</span></div><div class="ef-preview-tabs" role="tablist" aria-label="预览内容">'+[['original','原文件'],['parsed','解析文本']].map(([key,label])=>'<button role="tab" aria-selected="'+(efView.tab===key)+'" class="'+(efView.tab===key?'active':'')+'" data-action="ef-preview-tab" data-tab="'+key+'">'+label+'</button>').join('')+'</div></div><div class="ef-preview-content" id="ef-raw-content" '+(efView.tab!=='original'?'hidden':'')+'>'+previewMessage(allowed?'正在打开原始文件':'无预览权限',allowed?'可在右侧核对、调整提取字段。':'请联系资料管理员开通查看权限。')+'</div><div class="ef-preview-content" id="ef-parsed-content" '+(efView.tab!=='parsed'?'hidden':'')+'>'+(allowed?previewParsedMarkup(d):previewMessage('无预览权限','请联系资料管理员。'))+'</div>':'<div class="ef-empty"><span class="ef-empty-symbol">'+I('file')+'</span><h2>添加资料后，在这里查看原文</h2><p>先添加资料，再在右侧设置想提取的信息。</p>'+B(I('plus','icon-sm')+'添加资料','add-tool-materials','soft')+'</div>')+'</section>';}
workbench=function(){if(state.toolId!=='extract')return efBase.workbench();const task=currentTask();ewConfig();manage=false;ewView.checked=[];if(task&&efView.taskId!==task.id){efView.taskId=task.id;efView.panel='preview';}if(!task){efView.taskId=null;const ids=ewDocs().map(d=>d.id);if(!ids.includes(ws().preview))ws().preview=ids[0]||null;efChoices();}let header=ewHeader(task);if(!task)header=header.replace(/<div class="ew-steps">.*?<\/div>/,'').replace(/<span class="ew-ready">.*?<\/span>/,'');let materials=efMaterials();const panel=efView.panel;return '<div class="ew-workspace ef-workspace '+(task?'ef-task':'ef-preparing')+'">'+header+'<nav class="ef-mobile-tabs" aria-label="提取工作区">'+[['materials','已选资料 '+ewDocs().length],['preview',task?'提取结果':'查看原文'],['fields','提取内容 '+ewConfig().fieldDefs.length]].map(([key,label])=>'<button data-action="ef-panel" data-panel="'+key+'" class="'+(panel===key?'active':'')+'">'+label+'</button>').join('')+'</nav><div class="ew-grid '+(task&&!configExpanded?'ew-without-config':'')+'" data-ef-panel="'+panel+'">'+materials+'<main class="ew-center">'+(task?ewTaskArea(task):efPreview())+'</main>'+(!task||configExpanded?configPanel():'')+'</div></div>';};
function efMountPreview(){if(!efPreparing()||modal==='source')return;const d=file(ws().preview);if(!d||!auditFileAccess(d).preview)return;if(!efView.preview||efView.preview.id!==d.id)efView.preview={id:d.id,inline:true,rawPage:1,rawZoom:'fit'};const width=$('#ef-raw-content')?.clientWidth||0;if(!activeFilePreview||activeFilePreview.data!==efView.preview){efView.fitWidth=width;previewEnsure(efView.preview);}else if(activeFilePreview.pdf&&width>0&&Math.abs(width-(efView.fitWidth||0))>2&&(efView.preview.rawZoom||'fit')==='fit'){efView.fitWidth=width;previewPaintRaw(activeFilePreview);}}
render=function(){
 // Preserve the document surface (including PDF page, Word iframe and scroll) during scope/config edits.
 const oldRoot=$('#ef-raw-content'),oldSession=activeFilePreview,oldScroll=$('.ef-fields-scroll')?.scrollTop||0;
 const keep=efPreparing()&&oldRoot&&oldSession?.data.inline&&oldSession.id===ws().preview&&auditFileAccess(file(ws().preview)).preview;
 if(keep)oldRoot.remove();else if(oldSession?.data.inline)previewRelease();
 efBase.render();const root=$('#ef-raw-content');if(keep&&root&&efPreparing()&&ws().preview===oldSession.id)root.replaceWith(oldRoot);else if(keep)previewRelease();
 if(state.view==='tool'&&state.toolId==='extract'){const scroll=$('.ef-fields-scroll');if(scroll)scroll.scrollTop=efView.resetFields?0:oldScroll;efView.resetFields=false;efRefreshCounts();efMountPreview();}
};
handleAction=function(action,el){
 const extract=state.view==='tool'&&state.toolId==='extract',index=+el?.dataset?.index;
 if(extract&&action==='ew-manage')return;
 if(efPreparing()&&action==='ef-remove-material'){ewView.checked=[el.dataset.id];return efBase.handleAction('ew-remove-checked',el);}
 if(efPreparing()&&action==='ef-save-template'){efCommit();if(efErrors())return toast(efErrors());const c=ewConfig(),folderId='xt-mine',draft={id:null,folderId,name:xtUniqueName((c.template||'提取字段')+' · 个人模板',folderId),description:'',rules:structuredClone(c.fieldDefs),prompt:c.prompt||'',config:structuredClone(c)};openModal('ef-save-template',{draft,error:''});return;}
 if(action==='ef-confirm-save-template'&&modal==='ef-save-template'){const draft=modalData.draft,folder=xtFolder(draft.folderId);if(!folder||folder.system||!xtFolderEdit(folder))return xtError('请选择有权限的个人分类。');xtSave();if(modal!=='ef-save-template'){const saved=xtAll().find(t=>!t.system&&t.folderId===draft.folderId&&t.name===draft.name.trim());if(saved){const c=ewConfig();c.template=saved.name;c.extractionTemplateId=saved.id;render();}}return;}
 if(efPreparing()&&action==='preview'){ws().preview=el.dataset.id;efView.panel='preview';render();return;}
 if(efPreparing()&&action==='ew-folder'){efView.attachmentScope={space:el.dataset.space,path:el.dataset.path};const key=el.dataset.space+'::'+el.dataset.path;ewView.closed=ewView.closed.includes(key)?ewView.closed.filter(k=>k!==key):[...ewView.closed,key];render();return;}
 if(extract&&action==='source'&&activeFilePreview?.data.inline)previewRelease();
 if(efPreparing()&&action==='ef-refresh-original'){previewRelease();render();return;}
 if(efPreparing()&&action==='ef-download-original'){const d=file(ws().preview),s=activeFilePreview;if(!auditFileAccess(d).download||!auditFileAccess(d).preview)return toast('当前没有此文件的下载权限。');if(!s?.data.inline||!s.file||!previewAlive(s))return toast('原始文件暂不可用，请稍后重试。');const url=URL.createObjectURL(s.file),a=document.createElement('a');a.href=url;a.download=d.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);return;}
 if(action==='ef-preview-tab'){efView.tab=el.dataset.tab;$$('.ef-preview-tabs button').forEach(b=>{b.classList.toggle('active',b.dataset.tab===efView.tab);b.setAttribute('aria-selected',String(b.dataset.tab===efView.tab));});$('#ef-raw-content').hidden=efView.tab!=='original';$('#ef-parsed-content').hidden=efView.tab!=='parsed';if(efView.tab==='original')efMountPreview();return;}
 if(extract&&action==='ew-config')efView.panel=configExpanded?'preview':'fields';
 if(action==='ef-panel'){efView.panel=el.dataset.panel;if(currentTask()&&efView.panel==='fields')configExpanded=true;render();$('.ew-grid')?.setAttribute('data-ef-panel',efView.panel);return;}
 if(efPreparing()&&action.startsWith('ef-field-')){const fields=efChoices();if(action==='ef-field-add'){if(fields.length>=200)return toast('最多保留200个字段，请先移除不需要的字段。');fields.push({name:'',description:''});}if(action==='ef-field-remove'){const removed=fields.splice(index,1)[0];efCommit();render();toast('已移除本次字段，原模板保留。',()=>{efChoices().splice(index,0,removed);efCommit();render();});return;}if(action==='ef-field-up'||action==='ef-field-down'){const to=index+(action==='ef-field-up'?-1:1);if(to<0||to>=fields.length)return;[fields[index],fields[to]]=[fields[to],fields[index]];}efCommit();render();if(action==='ef-field-add'){$('#ef-field-'+(fields.length-1))?.focus();$('#ef-field-'+(fields.length-1))?.scrollIntoView({block:'nearest'});}return;}
 if(efPreparing()&&action==='run'){efView.validationAttempted=true;efCommit();if(efErrors()){const names=efChoices().map(f=>f.name.trim());efView.invalidField=Math.max(0,names.findIndex(n=>!n||names.filter(v=>v===n).length>1));efView.panel='fields';render();} }
 if(efPreparing()&&action==='save-template'){efCommit();if(efErrors())return toast(efErrors());}
 return efBase.handleAction(action,el);
};
closeModal=function(){const wasSource=modal==='source',wasValidation=modal==='validation';efBase.closeModal();if(wasSource&&modal!=='source')efMountPreview();if(wasValidation&&!modal&&efPreparing()&&efView.invalidField!=null){const field=$('#ef-field-'+efView.invalidField);(field||$('[data-action=ef-field-add]'))?.focus();field?.scrollIntoView({block:'nearest'});delete efView.invalidField;}};
window.addEventListener('input',e=>{const el=e.target,k=el.dataset.efInput;if(!k||!efPreparing())return;e.stopImmediatePropagation();const field=efChoices()[+el.dataset.index];if(!field)return;field[k]=el.value;efCommit();efRefreshCounts();},true);
document.addEventListener('toggle',e=>{if(e.target.matches('.ef-settings')&&e.target.isConnected)efView.settings=e.target.open;},true);
document.addEventListener('click',e=>{$$('.ef-field-menu[open],.ef-preview-menu[open]').forEach(d=>{if(!d.contains(e.target)||e.target.closest('[data-action]'))d.open=false;});},true);
render();

window.addEventListener('keydown',e=>{if(e.key!=='Escape'||modal)return;const open=$('.ef-field-menu[open],.ef-preview-menu[open],.ef-settings[open]');if(open){e.preventDefault();e.stopImmediatePropagation();open.open=false;open.querySelector('summary')?.focus();}},true);

window.addEventListener('resize',()=>{$$('.ef-field-menu[open],.ef-preview-menu[open]').forEach(d=>d.open=false);requestAnimationFrame(efMountPreview);});
document.addEventListener('scroll',e=>{if(e.target.matches?.('.ef-fields-scroll'))$$('.ef-field-menu[open]').forEach(d=>d.open=false);},true);

// Menus escape the independently scrolling field pane and stay inside the viewport.
document.addEventListener('toggle',e=>{const d=e.target;if(!d.matches?.('.ef-field-menu,.ef-preview-menu')||!d.open)return;$$('.ef-field-menu[open],.ef-preview-menu[open]').forEach(x=>{if(x!==d)x.open=false;});const menu=d.querySelector('.lib-menu'),r=d.querySelector('summary').getBoundingClientRect();if(!menu)return;menu.style.position='fixed';menu.style.right='auto';menu.style.left=Math.max(8,Math.min(innerWidth-menu.offsetWidth-8,r.right-menu.offsetWidth))+'px';menu.style.top=Math.max(8,r.bottom+menu.offsetHeight+6>innerHeight?r.top-menu.offsetHeight-6:r.bottom+6)+'px';},true);
window.addEventListener('keydown',e=>{const menu=e.target.closest('.ef-field-menu,.ef-preview-menu');if(!menu||!['ArrowDown','ArrowUp','Home','End'].includes(e.key))return;e.preventDefault();e.stopImmediatePropagation();menu.open=true;const buttons=[...menu.querySelectorAll('button:not(:disabled)')],i=buttons.indexOf(document.activeElement);if(buttons.length)buttons[e.key==='Home'?0:e.key==='End'?buttons.length-1:e.key==='ArrowUp'?(i-1+buttons.length)%buttons.length:(i+1)%buttons.length].focus();},true);

// Own the disclosure state synchronously so a form rerender cannot reopen a just-closed panel.
document.addEventListener('click',e=>{const settings=$('.ef-settings');if(!settings)return;if(e.target.closest('.ef-settings>summary')){e.preventDefault();settings.open=!settings.open;efView.settings=settings.open;}else if(!settings.contains(e.target)){settings.open=false;efView.settings=false;}},true);

window.addEventListener('input',e=>{if(modal==='ef-save-template'&&e.target.dataset.efSave){e.stopImmediatePropagation();modalData.draft[e.target.dataset.efSave]=e.target.value;}},true);
window.addEventListener('change',e=>{if(modal==='ef-save-template'&&e.target.dataset.efSave){e.stopImmediatePropagation();modalData.draft[e.target.dataset.efSave]=e.target.value;}},true);

window.addEventListener('change',e=>{if(e.target.dataset.efChange!=='attachment-merge'||!efPreparing()||modal!=='attachments')return;e.stopImmediatePropagation();ws().config.merge=e.target.checked;persist();render();paintModal();},true);
